<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { learningApi } from '@/api/learning'
import { foundation,type Asset } from '@/api/foundation'
import { messageOf } from '@/api/client'
import type { KnowledgeBase,KnowledgePoint } from '@/api/types'
const bases=ref<KnowledgeBase[]>([]),points=ref<KnowledgePoint[]>([]),assets=ref<Asset[]>([]),generated=ref<Asset[]>([])
const base=ref(''),point=ref(''),parent=ref(''),count=ref(1),ungrounded=ref(false),busy=ref(false),error=ref(''),requestID=ref('')
const parents=computed(()=>assets.value.filter(a=>a.Kind==='question'&&a.PointID===point.value))
onMounted(async()=>{try{[bases.value,points.value,assets.value]=await Promise.all([learningApi.bases(),learningApi.points(),foundation.assets()]);base.value=bases.value[0]?.ID??'';point.value=points.value[0]?.ID??''}catch(e){error.value=messageOf(e)}})
async function generate(){if(busy.value)return;busy.value=true;error.value='';generated.value=[];if(!requestID.value)requestID.value=crypto.randomUUID()
try{generated.value=await foundation.generatePractice({RequestID:requestID.value,KnowledgeBaseID:base.value,PointID:point.value,ParentAssetID:parent.value,Count:count.value,AllowUngrounded:ungrounded.value});requestID.value='';assets.value=await foundation.assets()}catch(e){error.value=messageOf(e);requestID.value=''}finally{busy.value=false}}
</script>
<template><details class="card section"><summary>补充 AI 练习</summary><p>从所选资料库检索知识依据后创建新练习。非题库原题；参考答案可能有误，默认不计入学情。用户确认自己的作答正确／错误后才按自评计入。</p><div v-if="error" class="notice error" role="alert">{{error}}</div><form @submit.prevent="generate"><div class="grid two-col"><label class="field">知识库<select v-model="base" :disabled="busy" required><option v-for="b in bases" :key="b.ID" :value="b.ID">{{b.Name}}</option></select></label><label class="field">知识点<select v-model="point" :disabled="busy" @change="parent=''" required><option v-for="p in points" :key="p.ID" :value="p.ID">{{p.SubjectName}} · {{p.Name}}</option></select></label><label class="field">变式来源<select v-model="parent" :disabled="busy"><option value="">围绕知识点创建新练习</option><option v-for="a in parents" :key="a.ID" :value="a.ID">{{a.Title}}</option></select></label><label class="field">题目数量<input v-model.number="count" :disabled="busy" type="number" min="1" max="3" required/></label></div><label style="display:flex;gap:8px;align-items:center;margin:12px 0"><input v-model="ungrounded" type="checkbox" :disabled="busy" style="width:auto"/>知识依据不足时，仍允许生成明确标注“缺少资料支持”的练习</label><p class="muted">点击会调用已配置模型；每次最多3题，24小时最多5次请求（失败请求也计入次数）。同批同知识点练习按题族管理。</p><button class="primary" :disabled="busy||!base||!point">{{busy?'正在生成…':'生成 AI 练习'}}</button><RouterLink v-if="!bases.length" to="/exam408/resources">先创建资料库</RouterLink></form><article v-for="q in generated" :key="q.ID" class="section"><h3>{{q.Title}}</h3><p class="notice">{{q.Payload.Source}}</p><RouterLink class="secondary" :to="{path:'/exam408/assessment',query:{point:q.PointID,asset:q.ID}}">前往练习</RouterLink></article></details></template>
